INSERT INTO CustoEmpresa ( NumMovimento, EmpVinculada, CodigoParceiro, CodHistorico, DataMovto, ValorDebito, ValorCredito, Complemento, Plano1, Plano2, Plano3, ContaFinanceira, Confirmado, Integracao, DataPagto, DataVencto, MovPagtoLote, SelPagtoLote, Observacao, NumDoc, CodImovel, AgrupadorVenda, ClassificacaoVenda, SofreReajuste, IndiceReajuste, CodAtribuiParceiro, CodAtribuiEmpresa, CodAnteriorParceiro, CodAnteriorEmpresa, Efetuado, LinkVenda, PagoAntecipado, ValorReajustado, ReferenteNotaFiscal, PagamentoLote, PadraoRelatorio, SomenteIntegracao, AnoOcorrenciaMensal, MesOcorrenciaMensal, EmitirCheque, ChequeEmitido, ValorOriginalImovel, CodigoCondPagto )
SELECT [F Movimento Contas].NumMovimento, [F Movimento Contas].EmpVinculada, [F Movimento Contas].CodigoParceiro, [F Movimento Contas].CodHistorico, [F Movimento Contas].DataMovto, [F Movimento Contas].ValorDebito, [F Movimento Contas].ValorCredito, [F Movimento Contas].Complemento, [F Movimento Contas].Plano1, [F Movimento Contas].Plano2, [F Movimento Contas].Plano3, [F Movimento Contas].ContaFinanceira, [F Movimento Contas].Confirmado, [F Movimento Contas].Integracao, [F Movimento Contas].DataPagto, [F Movimento Contas].DataVencto, [F Movimento Contas].MovPagtoLote, [F Movimento Contas].SelPagtoLote, [F Movimento Contas].Observacao, [F Movimento Contas].NumDoc, [F Movimento Contas].CodImovel, [F Movimento Contas].AgrupadorVenda, [F Movimento Contas].ClassificacaoVenda, [F Movimento Contas].SofreReajuste, [F Movimento Contas].IndiceReajuste, [F Movimento Contas].CodAtribuiParceiro, [F Movimento Contas].CodAtribuiEmpresa, [F Movimento Contas].CodAnteriorParceiro, [F Movimento Contas].CodAnteriorEmpresa, [F Movimento Contas].Efetuado, [F Movimento Contas].LinkVenda, [F Movimento Contas].PagoAntecipado, [F Movimento Contas].ValorReajustado, [F Movimento Contas].ReferenteNotaFiscal, [F Movimento Contas].PagamentoLote, [F Movimento Contas].PadraoRelatorio, [F Movimento Contas].SomenteIntegracao, [F Movimento Contas].AnoOcorrenciaMensal, [F Movimento Contas].MesOcorrenciaMensal, [F Movimento Contas].EmitirCheque, [F Movimento Contas].ChequeEmitido, [F Movimento Contas].ValorOriginalImovel, [F Movimento Contas].CodigoCondPagto
FROM [F Movimento Contas]
WHERE ((([F Movimento Contas].EmpVinculada)=Formulários![Relatorio Custos Empresa]!CodigoVinculada) And (([F Movimento Contas].Plano1)<>1) And (([F Movimento Contas].DataPagto)>=Formulários![Relatorio Custos Empresa]!DTInicial And ([F Movimento Contas].DataPagto)<=Formulários![Relatorio Custos Empresa]!DTFinal) And (([F Movimento Contas].SomenteIntegracao)=False));
